package com.cinebooking.commerce;
import com.cinebooking.domain.Voucher; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface VoucherRepository extends JpaRepository<Voucher,UUID>{ Optional<Voucher> findByCodeIgnoreCase(String code); List<Voucher> findAllByOrderByCreatedAtDesc(); List<Voucher> findByOwnerUserIdIsNullOrderByCreatedAtDesc(); List<Voucher> findByActiveTrueAndOwnerUserIdIsNullOrderByCreatedAtDesc(); List<Voucher> findByOwnerUserIdOrderByCreatedAtDesc(UUID ownerUserId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select v from Voucher v where upper(v.code)=upper(:code)") Optional<Voucher> findByCodeForUpdate(@Param("code") String code); }
